def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    if not text:
        return []

    def parse_lines(text: str) -> list[str]:
        # Metnin sonundaki tek satır sonu yeni bir kayıt oluşturmaz
        if text.endswith('\n'):
            text = text[:-1]
        if text.endswith('\r\n'):
            text = text[:-2]

        # \r\n'leri \n'ye çevirerek işleme kolaylık sağlıyoruz ama \r\n'leri bozmadan ayırmalıyız.
        # Ancak kural \r\n ile ayrılır diyor. 
        # Satırları ayırırken \r\n ve \n karakterlerini dikkate almalıyız.
        lines = []
        current_line = []
        i = 0
        while i < len(text):
            current_line.append(text[i])
            if text[i:i+2] == '\r\n':
                current_line.append(text[i+1])
                lines.append("".join(current_line))
                current_line = []
                i += 2
                continue
            elif text[i] == '\n' or text[i] == '\r':
                lines.append("".join(current_line))
                current_line = []
                i += 1
                continue
            else:
                i += 1
        if current_line:
            lines.append("".join(current_line))
        return lines

    lines = parse_lines(text)
    result = []

    for line in lines:
        row = []
        i = 0
        n = len(line)

        # Eğer satır tamamen boşsa (boş bir satır ortada ise [""])
        if not line:
            row.append("")
            result.append(row)
            continue

        while i < n:
            if line[i] == '"':
                # Tırnaklı alan başlıyor
                field = []
                i += 1 # tırnağı atla
                found_closing = False

                while i < n:
                    if line[i:i+2] == '""':
                        field.append('"')
                        i += 2
                    elif line[i] == '"':
                        # Tırnak kapandı
                        found_closing = True
                        i += 1
                        # Kapanan tırnaktan hemen sonra ayırıcı veya satır sonu gelmeli
                        if i < n and line[i] not in (delimiter, '\n', '\r'):
                            raise ValueError(f"Hatalı karakter: tırnaktan hemen sonra '{line[i]}' geldi.")
                        if i < n and line[i] in (delimiter, '\n', '\r'):
                            # Ayırıcı ise bir sonraki adıma hazırlık
                            pass
                        break
                    else:
                        field.append(line[i])
                        i += 1

                if not found_closing:
                    raise ValueError("Kapanmayan tırnak.")

                row.append("".join(field))

                # Eğer tırnaktan sonra ayırıcı varsa ayırıcıyı geç
                if i < n and line[i] == delimiter:
                    i += 1
                    # Eğer ayırıcı satır sonundaysa ve bir sonraki karakter yoksa boş alan eklemesi gerekebilir
                    if i == n:
                        row.append("")
                elif i < n and line[i] in ('\n', '\r'):
                    pass # Zaten satır bitti
                elif i < n:
                     # Bu kısım zaten hata fırlatacak olan tırnak sonrası kontrolünde yakalanmalı
                     pass

            else:
                # Tırnaksız alan
                start = i
                while i < n and line[i] != delimiter:
                    if line[i] == '\n' or line[i] == '\r':
                        break
                    i += 1
                row.append(line[start:i])

                if i < n and line[i] == delimiter:
                    i += 1
                    # Eğer ayırıcı satır sonundaysa boş alan ekle
                    if i == n:
                        row.append("")
                    elif i < n and line[i] in ('\n', '\r'):
                        row.append("")

        result.append(row)

    return result

