def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    if not text:
        return []

    # 1. Metnin sonundaki tek bir satır sonunu temizle (kural gereği)
    # Eğer metin "\n\n" ise, sonuncu \n çıkarılır -> "\n" kalır.
    # "\n" -> [[""], [""]] olur.
    if text.endswith('\r\n'):
        text = text[:-2]
    elif text.endswith('\n') or text.endswith('\r'):
        text = text[:-1]

    # Eğer metin tamamen temizlendiyse boş döner
    if not text:
        return []

    # 2. Satırları ayır (\n, \r\n, \r)
    lines = []
    current_line = []
    i = 0
    n = len(text)
    while i < n:
        if text[i:i+2] == '\r\n':
            lines.append("".join(current_line))
            current_line = []
            i += 2
        elif text[i] == '\n' or text[i] == '\r':
            lines.append("".join(current_line))
            current_line = []
            i += 1
        else:
            current_line.append(text[i])
            i += 1
    lines.append("".join(current_line))

    # 3. Her satırı parse et
    result = []
    for line in lines:
        if not line:
            result.append([""])
            continue

        row = []
        i = 0
        ln = len(line)

        while i < ln:
            # Alanın başlangıcı
            if line[i] == '"':
                # Tırnaklı alan
                i += 1
                field_chars = []
                found_closing = False
                while i < ln:
                    if line[i:i+2] == '""':
                        field_chars.append('"')
                        i += 2
                    elif line[i] == '"':
                        found_closing = True
                        i += 1
                        # Kural: Tırnaktan sonra ayırıcı veya satır sonu gelmeli
                        if i < ln and line[i] not in (delimiter, '\n', '\r'):
                            raise ValueError("Hatalı karakter: Tırnaktan hemen sonra ayırıcı/satır sonu gelmeli.")
                        break
                    else:
                        field_chars.append(line[i])
                        i += 1

                if not found_closing:
                    raise ValueError("Kapanmayan tırnak.")

                row.append("".join(field_chars))

                # Ayırıcı kontrolü (Eğer ayırıcıya çarptıysa ve sonraki karakter de ayırıcı değilse)
                if i < ln and line[i] == delimiter:
                    i += 1
                    if i == ln:
                        row.append("")
                elif i < ln and line[i] in ('\n', '\r'):
                    pass
                elif i < ln and line[i] != delimiter and line[i] not in ('\n', '\r'):
                    # Bu durum yukarıdaki tırnak kontrolünde yakalanmış olmalıydı ama garantiye alalım
                    raise ValueError("Hatalı karakter.")
            else:
                # Tırnaksız alan
                start = i
                while i < ln and line[i] != delimiter and line[i] not in ('\n', '\r'):
                    i += 1
                row.append(line[start:i])

                if i < ln and line[i] == delimiter:
                    i += 1
                    if i == ln:
                        row.append("")
                    elif i < ln and line[i] in ('\n', '\r'):
                        row.append("")

        # Boş satır değilse ama döngü sonunda row boşsa (bu durum aslında pek mümkün değil)
        if not row:
            row = [""]

        result.append(row)

    return result

