        ('"a","b","c"', ",", [["a", "b", "c"]]]),
        ('"a,b","c"', ",", [["a,b", "c"]]]),
        ('"a ""quoted"" b","c"', ",", [["a \"quoted\" b", "c"]]]),
        ('a,"b ""quoted"" c",d', ",", [["a", "b \"quoted\" c", "d"]]]),
        ('a b,c', ",", [["a b", "c"]]]),
        (' a , b ', ",", [[" a ", " b "]]),
    ]

